/**
 * A live monitor. The list re-reads every 30 seconds while the tab is visible and once when the
 * viewer comes back to it; a write anywhere in the portal that invalidates these reads refreshes
 * it too. The viewer can select rows with checkboxes and download the selection as CSV.
 */
import { createRoot } from 'react-dom/client';
import { useState } from 'react';
import { Checkbox, SurfaceApp, toCsv, toast, useDownload, useQuery } from '@cynap/surface-sdk';

import './styles.css';

/** The org's entity type and the columns to show and export. Replace both. */
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
const COLUMNS = ['name', 'stage', 'updated_at'];
const REFRESH_MS = 30_000;

type Row = Record<string, unknown>;
const isRecord = (value: unknown): value is Row => typeof value === 'object' && value !== null && !Array.isArray(value);

function readRows(payload: unknown): Row[] | null {
  return isRecord(payload) && Array.isArray(payload.rows) ? payload.rows.filter(isRecord) : null;
}

function Monitor() {
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set());
  const download = useDownload();
  const rows = useQuery(
    'knowledge_query_data',
    { tool: 'knowledge_advanced_query', params: { entity_type: ENTITY_TYPE, sort_by: 'updated_at', sort_order: 'desc', limit: 100 } },
    { parse: readRows, refreshInterval: REFRESH_MS, refetchOnVisible: true, keepPrevious: true }
  );
  const list = rows.data ?? [];
  const idOf = (row: Row) => String(row.id);

  function toggle(id: string, on: boolean) {
    setSelected((previous) => {
      const next = new Set(previous);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });
  }

  async function onDownload() {
    const chosen = list.filter((row) => selected.has(idOf(row)));
    const outcome = await download({ filename: 'selection.csv', mimeType: 'text/csv', text: toCsv(chosen, COLUMNS) });
    if (outcome === 'unsupported') toast('Downloads are not available here.', { tone: 'error' });
    else if (outcome === 'failed') toast('The download failed.', { tone: 'error' });
  }

  return (
    <main className="tpl-page">
      <div className="tpl-row">
        <span className="tpl-muted">{rows.isFetching ? 'Refreshing…' : `${list.length} records`}</span>
        <button type="button" className="tpl-button" disabled={selected.size === 0} onClick={() => void onDownload()}>
          Download {selected.size} as CSV
        </button>
      </div>
      <ul className="tpl-list" aria-label="Records">
        {list.map((row) => {
          const id = idOf(row);
          return (
            <li key={id} className="tpl-row">
              <Checkbox
                checked={selected.has(id)}
                onCheckedChange={(state) => toggle(id, state === true)}
                aria-label={`Select ${String(row.name ?? id)}`}
              />
              {COLUMNS.map((column) => (
                <span key={column}>{String(row[column] ?? '')}</span>
              ))}
            </li>
          );
        })}
      </ul>
    </main>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'ops-monitor', version: '1.0.0' }}>
      <Monitor />
    </SurfaceApp>
  );
}

